L["Your target, and theirs is running out."] = "Euer Ziel, Stärkungszauber läuft bald ab."
L["Nearby, and theirs is running out."] = "In der Nähe, Stärkungszauber läuft bald ab."
L["In your group and missing it."] = "In Eurer Gruppe, Stärkungszauber fehlt."
L["Your target, and missing it."] = "Euer Ziel, Stärkungszauber fehlt."
L["Nearby and missing it."] = "In der Nähe, Stärkungszauber fehlt."
L["In your group."] = "In Eurer Gruppe."
L["Your target."] = "Euer Ziel."
L["Nearby."] = "In der Nähe."
L["On your friends list."] = "Auf Eurer Freundesliste."
L["In your guild."] = "In Eurer Gilde."
L["Theirs expires in %s."] = "Stärkungszauber endet in %s."
L["Buff state unreadable on this build -- they may already have it."] = "Stärkungszauber in dieser Version nicht auslesbar – womöglich schon vorhanden."
L["Not checking whether they have it -- set by your options."] = "Ob schon vorhanden, wird nicht geprüft – so in Euren Optionen eingestellt."
L["Will run:"] = "Wird ausgeführt:"
L["Click to cast. %s for options."] = "Klickt zum Wirken. %s für die Optionen."
L["Right-click to skip this one."] = "Rechtsklick: überspringen."
L["Shift-right-click to let this favour go."] = "Umschalt-Rechtsklick: Gefallen verfallen lassen."
L["Shift-right-click to put them on your never-offer list."] = "Umschalt-Rechtsklick: auf die Ausschlussliste setzen."
L["|cffffcc66Does nothing:|r %s."] = "|cffffcc66Bewirkt nichts:|r %s."
L["Runs your |cffffd100/manners try|r macro against |cffffffff%s|r."] = "Führt Euer Makro |cffffd100/manners try|r auf |cffffffff%s|r aus."
L["Runs your |cffffd100/manners try|r macro against |cffffffffthem|r."] = "Führt Euer Makro |cffffd100/manners try|r auf |cffffffffdiese Person|r aus."
L["Casts |cffffffff%s|r on you; it reaches your party from there."] = "Wirkt |cffffffff%s|r auf Euch; so erreicht der Zauber Eure Gruppe."
L["Targets |cffffffff%s|r, casts |cffffffff%s|r."] = "Nimmt |cffffffff%s|r ins Ziel, wirkt |cffffffff%s|r."
L["Targets |cffffffffthem|r, casts |cffffffff%s|r."] = "Nimmt |cffffffffdiese Person|r ins Ziel, wirkt |cffffffff%s|r."
L["Hands your own target back afterwards."] = "Stellt danach Euer Ziel wieder her."
L["They are already your target, so they stay targeted."] = "Ist bereits Euer Ziel und bleibt es."
L["|cffffcc66Leaves them targeted|r -- your own target is not restored."] = "|cffffcc66Lässt diese Person im Ziel|r – Euer Ziel wird nicht wiederhergestellt."
L["Says: |cffffffff%s|r"] = "Sagt: |cffffffff%s|r"
L["PREVIEW"] = "VORSCHAU"
L["preview off."] = "Vorschau aus."
L["|cffff8080not during a fight|r -- the preview can be shown once it ends."] = "|cffff8080nicht im Kampf|r – die Vorschau lässt sich nach dem Kampf zeigen."
L["somebody real is on the prompt, so there is nothing to preview -- open |cffffd100/manners|r to style it; a preview holds while that window is open."] = "ein echter Spieler steht in der Anzeige, also gibt es keine Vorschau – öffnet |cffffd100/manners|r, um sie zu gestalten; solange dieses Fenster offen ist, bleibt eine Vorschau stehen."
L["preview on -- it stays while the options window is open, then %ds longer, or |cffffd100/manners test|r to stop."] = "Vorschau an – sie bleibt, solange das Optionsfenster offen ist, danach noch %d s, oder beendet sie mit |cffffd100/manners test|r."
L["the prompt has moved on to |cffffffff%s|r -- press again to buff them."] = "die Anzeige zeigt jetzt |cffffffff%s|r – noch ein Klick stärkt diese Person."
L["|cffff8080could not buff|r |cffffffff%s|r"] = "|cffffffff%s|r |cffff8080nicht gestärkt|r"
L["|cffff8080could not buff|r |cffffffffthem|r"] = "|cffffffffdiese Person|r |cffff8080nicht gestärkt|r"
L["|cffe8e0a0sent to|r |cffffffff%s|r"] = "|cffe8e0a0gesendet an|r |cffffffff%s|r"
L["|cffe8e0a0sent to|r |cffffffffthem|r"] = "|cffe8e0a0gesendet an|r |cffffffffdiese Person|r"
L["|cff8ce88cbuffed|r |cffffffff%s|r"] = "|cffffffff%s|r |cff8ce88cgestärkt|r"
L["|cff8ce88cbuffed|r |cffffffffthem|r"] = "|cffffffffdiese Person|r |cff8ce88cgestärkt|r"
L["the game confirmed it"] = "vom Spiel bestätigt"
L["still armed by the fight"] = "im Kampf noch scharf"
L["nothing to buff"] = "niemand zu stärken"
L["nothing this character can cast -- a press still casts what the fight froze"] = "dieser Charakter kann nichts wirken – ein Klick wirkt noch, was der Kampf eingefroren hat"
L["nothing this character can cast -- nothing armed, and the panel cannot go"] = "dieser Charakter kann nichts wirken – nichts scharf, Anzeige bleibt bis Kampfende"
L["preview off -- timed out."] = "Vorschau aus – Zeit abgelaufen."
L["preview off -- somebody real turned up."] = "Vorschau aus – ein echter Spieler ist aufgetaucht."
L["Someone %d"] = "Jemand %d"
L["switched off -- a press still casts what the fight froze"] = "ausgeschaltet – ein Klick wirkt noch, was der Kampf eingefroren hat"
L["switched off -- nothing armed, and the panel cannot go"] = "ausgeschaltet – nichts scharf, Anzeige bleibt bis Kampfende"
L["Drag to move"] = "Zum Verschieben ziehen"
L["not buffing while unlocked"] = "stärkt nicht, solange entsperrt"
L["unlocked -- a press still casts what the fight froze"] = "entsperrt – ein Klick wirkt noch, was der Kampf eingefroren hat"
L["unlocked -- nothing armed, and the panel cannot go"] = "entsperrt – nichts scharf, Anzeige bleibt bis Kampfende"
L["held -- in combat"] = "eingefroren – im Kampf"
L["held -- a press still casts what the fight froze"] = "eingefroren – ein Klick wirkt noch, was der Kampf eingefroren hat"
L["held -- nothing armed, and the panel cannot go"] = "eingefroren – nichts scharf, Anzeige bleibt bis Kampfende"
L["ready in %.1fs"] = "bereit in %.1f s"
L["%s |cffffd100snoozed until %s|r"] = "%s |cffffd100pausiert bis %s|r"
L["%s |cffff8080off|r"] = "%s |cffff8080aus|r"
L["%s |cff80e0801 waiting|r"] = "%s |cff80e0801 offen|r"
L["%s |cff80e080%d waiting|r"] = "%s |cff80e080%d offen|r"
L["Automatic"] = "Automatisch"
L["%s |cff808080(not learned)|r"] = "%s |cff808080(nicht erlernt)|r"
L["%s |cff808080(mana users only)|r"] = "%s |cff808080(nur Manaklassen)|r"
L["%s |cff808080(your group only)|r"] = "%s |cff808080(nur Eure Gruppe)|r"
L["This character has nothing it can cast on another player."] = "Dieser Charakter hat nichts, was er auf einen anderen Spieler wirken kann."
L["You have not learned any of these yet, so nobody will be offered anything."] = "Ihr habt noch keinen dieser Zauber erlernt, also bekommt niemand etwas angeboten."
L["Automatic never offers %s -- nobody standing in a city wants it -- so nobody will be offered anything."] = "„Automatisch“ bietet %s nie an – in einer Stadt will das niemand –, also bekommt niemand etwas angeboten."
L["Pin it in the dropdown above if you want it given out anyway."] = "Legt den Zauber im Auswahlmenü oben fest, wenn er trotzdem verteilt werden soll."
L["Every spell you have learned is switched off, so nothing is offered until you switch one back on or learn one of the others."] = "Alle Zauber, die Ihr erlernt habt, sind ausgeschaltet, also wird nichts angeboten, bis Ihr einen wieder einschaltet oder einen der anderen erlernt."
L["Every spell below is switched off, so the prompt will never appear."] = "Alle Zauber unten sind ausgeschaltet, also erscheint die Anzeige nie."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. |cffffd100Always offer|r does not check what they carry, so it can replace one of yours."] = "Eure Segen ersetzen einander, also verteilt „Automatisch“ nur den ersten aus %s, der passt. |cffffd100Immer anbieten|r prüft nicht, was jemand trägt, und kann daher einen von Euren ersetzen."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Where the game hides which blessing somebody carries, it can replace one of yours."] = "Eure Segen ersetzen einander, also verteilt „Automatisch“ nur den ersten aus %s, der passt. Wo das Spiel verbirgt, welchen Segen jemand trägt, kann er einen von Euren ersetzen."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Anybody already carrying one of yours is left alone."] = "Eure Segen ersetzen einander, also verteilt „Automatisch“ nur den ersten aus %s, der passt. Wer schon einen von Euren trägt, wird in Ruhe gelassen."
L["Automatic offers the first of these they are missing, in this order: %s."] = "„Automatisch“ bietet den ersten dieser Zauber an, der fehlt, in dieser Reihenfolge: %s."
L["Where the game will not say what somebody is carrying, it moves down the list each time instead of offering the same one over and over."] = "Wo das Spiel nicht verrät, was jemand trägt, wird jedes Mal der nächste auf der Liste angeboten statt immer wieder derselbe."
L["Only |cffffffff%s|r is offered, to everybody, whatever else they are missing. The per-spell switches come back with Automatic."] = "Nur |cffffffff%s|r wird angeboten, und zwar allen, egal was ihnen sonst noch fehlt. Die Schalter für die einzelnen Zauber erscheinen wieder mit „Automatisch“."
L["You have pinned %s, which you have not learned."] = "Ihr habt %s festgelegt, aber diesen Zauber noch nicht erlernt."
L["Nothing will be offered to anybody until you learn it or switch back to Automatic."] = "Niemand bekommt etwas angeboten, bis Ihr den Zauber erlernt oder wieder auf „Automatisch“ umstellt."
L["Switched off, this one is never offered to anybody and Automatic walks straight past it. Everything else carries on as before."] = "Ausgeschaltet wird dieser Zauber niemandem angeboten, und „Automatisch“ überspringt ihn einfach. Alles andere läuft weiter wie bisher."
L["Who to buff"] = "Wen stärken"
L["Buffs"] = "Stärkungszauber"
L["Buff to cast"] = "Welcher Stärkungszauber"
L["Sources"] = "Wer infrage kommt"
L["Nothing below is switched on, so the prompt will never appear."] = "Unten ist nichts eingeschaltet, also erscheint die Anzeige nie."
L["People who buffed me"] = "Wer mich gestärkt hat"
L["Watch for buffs cast on you and offer to return them. What you cast reaches only your own party -- in a raid, your own subgroup -- so somebody outside it is offered once they join."] = "Manners achtet auf Stärkungszauber, die auf Euch gewirkt werden, und bietet an, den Gefallen zu erwidern. Was Ihr wirkt, erreicht nur Eure eigene Gruppe – im Schlachtzug Eure Untergruppe –, also bekommt jemand von außerhalb erst etwas angeboten, sobald er beitritt."
L["Watch for buffs cast on you and offer to return them. What you cast reaches your group only, so somebody outside it is offered once they join."] = "Manners achtet auf Stärkungszauber, die auf Euch gewirkt werden, und bietet an, den Gefallen zu erwidern. Was Ihr wirkt, erreicht nur Eure Gruppe, also bekommt jemand von außerhalb erst etwas angeboten, sobald er beitritt."
L["Watch for buffs cast on you and offer to return them. Works on strangers who are not in your group."] = "Manners achtet auf Stärkungszauber, die auf Euch gewirkt werden, und bietet an, den Gefallen zu erwidern. Funktioniert auch bei Fremden außerhalb Eurer Gruppe."
L["Only count real class buffs"] = "Nur echte Klassen-Stärkungszauber zählen"
L["A shield, a heal-over-time or a trinket proc is not a favour owed. Leave this on unless you want every incoming aura to count."] = "Ein Schild, eine Heilung über Zeit oder ein Schmuckstück-Effekt ist kein offener Gefallen. Lasst das eingeschaltet, außer Ihr wollt, dass jede eingehende Aura zählt."
L["My party and raid"] = "Meine Gruppe und mein Schlachtzug"
L["Nearby players not in my group"] = "Spieler in der Nähe außerhalb meiner Gruppe"
L["Offer passers-by who are missing the buff. Seen through nameplates, your target, your focus and your mouseover."] = "Passanten, denen der Stärkungszauber fehlt, bekommen ihn angeboten. Erkannt über Namensplaketten, Euer Ziel, Euren Fokus und Euer Mouseover."
L["Everything you can offer is cast on yourself and heard by your party, so there is nothing to give a passer-by."] = "Alles, was Ihr anbieten könnt, wirkt Ihr auf Euch selbst, und von dort erreicht es Eure Gruppe, also gibt es für Passanten nichts."
L["People who ask me for it"] = "Wer mich darum bittet"
L["For a minute, offer your buff to somebody who asks for it in /say, /yell, group chat or a whisper -- \"int pls\", \"fort?\", \"buffs please\"."] = "Wer in /say, /yell, im Chat Eurer Gruppe oder per Flüstern um Euren Stärkungszauber bittet, bekommt ihn eine Minute lang angeboten – etwa bei „int pls“, „fort?“ oder „buffs please“."
L["Only short requests count, and in a fight only whispers. Nothing is said back to them."] = "Es zählen nur kurze Anfragen, und im Kampf nur Geflüstertes. Niemand bekommt eine Antwort."
L["Off at first: reading chat is guesswork, so now and then somebody only talking about a buff is offered one."] = "Zunächst ausgeschaltet: Den Chat zu lesen ist Rätselraten, daher bekommt ab und zu jemand, der nur über einen Stärkungszauber redet, einen angeboten."
L["Wording: asked for it"] = "Wortlaut: hat darum gebeten"
L["The prompt's second line for somebody who asked for the buff in chat."] = "Die zweite Zeile der Anzeige für jemanden, der im Chat um den Stärkungszauber gebeten hat."
L["Who comes first"] = "Reihenfolge"
L["Whoever I have targeted comes first"] = "Mein Ziel kommt zuerst"
L["Your target outranks a favour owed, but only when the game can read that they are missing the buff."] = "Euer Ziel geht einem offenen Gefallen vor, aber nur, wenn das Spiel auslesen kann, dass der Stärkungszauber fehlt."
L["Not while |cffffd100If they already have the buff|r is set to Always offer, under When, since nothing is read then."] = "Nicht, solange |cffffd100Wenn sie den Stärkungszauber schon haben|r auf dem Reiter „Wann“ auf „Immer anbieten“ steht, denn dann wird nichts ausgelesen."
L["Mouseover is left out: the prompt would flicker as the cursor crossed the screen."] = "Mouseover ist ausgenommen: Die Anzeige würde flackern, während der Mauszeiger über den Bildschirm wandert."
L["My friends and guildmates come before the others"] = "Meine Freunde und Gildenmitglieder kommen vor den anderen"
L["A friend or guildmate goes ahead of the other passers-by, or of the rest of your group. It only changes the order; nobody is added or left out."] = "Freunde und Gildenmitglieder sind vor den anderen Passanten oder vor dem Rest Eurer Gruppe dran. Das ändert nur die Reihenfolge; niemand kommt hinzu oder fällt weg."
L["Friends include Battle.net friends. When the game will not say whether somebody is a friend, they are ranked like anybody else."] = "Zu den Freunden zählen auch Battle.net-Freunde. Wenn das Spiel nicht verrät, ob jemand ein Freund ist, wird diese Person wie alle anderen eingeordnet."
L["Who to skip"] = "Wen überspringen"
L["Mana-only buffs such as Arcane Intellect, Wisdom and Divine Spirit are wasted on warriors and rogues."] = "Reine Mana-Stärkungszauber wie Arkane Intelligenz, Segen der Weisheit und Göttlicher Willen sind an Krieger und Schurken verschwendet."
L["Hide players known to be out of range"] = "Spieler ausblenden, die sicher außer Reichweite sind"
L["When the game will not tell us the range -- common on this client -- they are still offered."] = "Wenn das Spiel die Reichweite nicht verrät – auf diesem Client häufig –, bekommen diese Spieler trotzdem etwas angeboten."
L["How near a passer-by has to be"] = "Wie nah ein Passant sein muss"
L["Being in range is not the same as being near: Arcane Intellect and its like reach about thirty yards, which in a city is everybody on the screen."] = "In Reichweite zu sein ist nicht dasselbe, wie in der Nähe zu sein: Arkane Intelligenz und ähnliche Zauber reichen etwa dreißig Meter weit, und das ist in einer Stadt jeder auf dem Bildschirm."
L["|cffffd100Anywhere I can cast|r -- about thirty yards, as it was."] = "|cffffd100Überall, wo ich wirken kann|r – etwa dreißig Meter, wie bisher."
L["|cffffd100Nearby|r -- about ten yards."] = "|cffffd100In der Nähe|r – etwa zehn Meter."
L["|cffffd100Right beside me|r -- about five yards."] = "|cffffd100Direkt neben mir|r – etwa fünf Meter."
L["Only passers-by are measured; not somebody who buffed you, your group, or whoever you targeted or focused."] = "Gemessen werden nur Passanten; nicht, wer Euch gestärkt hat, Eure Gruppe oder wen Ihr ins Ziel oder in den Fokus genommen habt."
L["The game gives no exact distance, so this is measured as closely as the client allows. When it cannot measure at all, everybody in casting range is offered."] = "Das Spiel nennt keine genaue Entfernung, daher wird so genau gemessen, wie der Client es zulässt. Wenn sich gar nicht messen lässt, bekommt jeder in Zauberreichweite etwas angeboten."
L["Only offer passers-by in cities and inns"] = "Passanten nur in Städten und Gasthäusern etwas anbieten"
L["Out in the world, passers-by are left alone; they are offered only where the game shows you as resting, which is in a city or an inn."] = "Draußen in der Welt werden Passanten in Ruhe gelassen; sie bekommen nur etwas angeboten, wenn Ihr Euch laut Spiel in einer Stadt oder einem Gasthaus aufhaltet."
L["Somebody who buffed you, your group, and whoever you have targeted or focused are offered anywhere."] = "Wer Euch gestärkt hat, Eure Gruppe sowie Euer Ziel und Euer Fokus bekommen überall etwas angeboten."
L["If the game will not say whether you are resting, passers-by are offered as usual."] = "Wenn das Spiel nicht verrät, ob Ihr in einer Stadt oder einem Gasthaus seid, bekommen Passanten wie gewohnt etwas angeboten."
L["Drop people who are probably gone"] = "Wahrscheinlich Weitergezogene entfernen"
L["Somebody who buffed you can rarely be range-checked afterwards. With this on, they count as in range for a while after their buff, then are let go."] = "Bei jemandem, der Euch gestärkt hat, lässt sich die Reichweite danach selten prüfen. Ist das eingeschaltet, gilt diese Person nach ihrem Stärkungszauber eine Weile als in Reichweite und wird danach entfernt."
L["Let them go after (seconds)"] = "Entfernen nach (Sekunden)"
L["How long somebody counts as in range after they buff you. It runs from their buff, not from when they walk off."] = "Wie lange jemand, der Euch gestärkt hat, als in Reichweite gilt. Die Zeit läuft ab dem Stärkungszauber, nicht ab dem Moment, in dem die Person weggeht."
L["Minimum level"] = "Mindeststufe"
L["Players below this are never offered. Somebody known only by name cannot be level-checked and is offered anyway."] = "Spieler unter dieser Stufe bekommen nie etwas angeboten. Wer nur dem Namen nach bekannt ist, lässt sich nicht auf die Stufe prüfen und bekommt trotzdem etwas angeboten."
L["Never offer"] = "Nie etwas anbieten"
L["Nobody is on the list. Shift-right-click the prompt to put whoever it is showing on it, or add a name below."] = "Niemand steht auf der Liste. Mit Umschalt-Rechtsklick auf die Anzeige setzt Ihr den angezeigten Spieler darauf, oder Ihr fügt unten einen Namen hinzu."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Eine Person steht auf der Liste. Sie bekommt nie etwas angeboten, weder als Passant noch als Mitglied Eurer Gruppe."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "%d Personen stehen auf der Liste. Sie bekommen nie etwas angeboten, weder als Passanten noch als Mitglieder Eurer Gruppe."
L["Somebody on it who buffs you is still offered the favour back. Shift-right-click them on the prompt to let that favour go."] = "Stärkt Euch jemand von der Liste, wird Euch trotzdem angeboten, den Gefallen zu erwidern. Mit Umschalt-Rechtsklick auf diese Person in der Anzeige lasst Ihr diesen Gefallen verfallen."
L["Add somebody by name"] = "Jemanden per Namen hinzufügen"
L["Spelled the way the prompt shows them. Capitals do not matter."] = "So geschrieben, wie die Anzeige den Namen zeigt. Groß- und Kleinschreibung spielt keine Rolle."
L["On the list"] = "Auf der Liste"
L["Take them off"] = "Von der Liste nehmen"
L["Clear the list"] = "Liste leeren"
L["Take everybody off the never-offer list?"] = "Alle von der Ausschlussliste nehmen?"
L["General"] = "Allgemein"
L["Enable"] = "Aktivieren"
L["Manners is switched off, so the prompt will never appear. Everything below is still saved."] = "Manners ist ausgeschaltet, also erscheint die Anzeige nie. Alles unten bleibt gespeichert."
L["Your class has no buffs it can cast on another player."] = "Eure Klasse hat keine Stärkungszauber, die sie auf einen anderen Spieler wirken kann."
L["Manners has nothing to offer here. It is still worth keeping installed on an alt that does."] = "Manners hat hier nichts anzubieten. Für einen anderen Charakter, der etwas anbieten kann, lohnt es sich trotzdem, Manners installiert zu lassen."
L["Manners could not work out what you can cast."] = "Manners konnte nicht herausfinden, was Ihr wirken könnt."
L["Either your class has nothing for other players, or the spell probe came back empty -- %s says which."] = "Entweder hat Eure Klasse nichts für andere Spieler, oder die Zauberabfrage kam leer zurück – %s verrät, was davon zutrifft."
L["How this works"] = "So funktioniert es"
L["Blizzard does not let an addon cast a spell by itself, so Manners works out who deserves a buff and puts them on the prompt. Click the prompt and it casts."] = "Blizzard lässt ein Addon keine Zauber von selbst wirken, also ermittelt Manners, wer einen Stärkungszauber verdient, und zeigt diese Person in der Anzeige. Klickt auf die Anzeige, und der Zauber wird gewirkt."
L["Putting it on a key"] = "Auf eine Taste legen"
L["Make the macro below and drag it onto a bar, or bind a key under Options > Keybindings > Manners."] = "Erstellt unten das Makro und zieht es auf eine Aktionsleiste, oder belegt eine Taste unter Optionen > Tastaturbelegung > Manners."
L["Getting started"] = "Erste Schritte"
L["Create the macro"] = "Makro erstellen"
L["Adds a macro called Manners containing %s. Drag it onto an action bar and it fires the prompt."] = "Legt ein Makro namens Manners an, das %s enthält. Zieht es auf eine Aktionsleiste, dann löst es die Anzeige aus."
L["Snooze"] = "Pausieren"
L["|cffffd100Snoozed until %s.|r In a fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "|cffffd100Pausiert bis %s.|r Im Kampf bleibt die Anzeige, wie sie bei Kampfbeginn war, und folgt der Pause, sobald der Kampf vorbei ist."
L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged, casting nothing, until you lock it."] = "|cffffd100Pausiert bis %s.|r Die Anzeige ist entsperrt, bleibt also zum Verschieben sichtbar und wirkt nichts, bis Ihr sie sperrt."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100Pausiert bis %s.|r Bis dahin keine Anzeige, aber wer Euch stärkt, wird trotzdem bemerkt."
L["Keep the prompt out of the way for a while without switching Manners off. It comes back when the time is up, or after a %s."] = "Blendet die Anzeige eine Weile aus, ohne Manners auszuschalten. Sie kommt zurück, wenn die Zeit um ist, oder nach einem %s."
L["Stop snoozing"] = "Pause beenden"
L["Minimap"] = "Minikarte"
L["Show minimap button"] = "Minikartensymbol anzeigen"
L["Manners stays in the addon compartment under the minimap either way."] = "Manners bleibt so oder so im Addon-Menü an der Minikarte."
L["Without it, |cffffd100/manners|r and the AddOns page in the game's options are the way in."] = "Ohne das Symbol erreicht Ihr Manners über |cffffd100/manners|r und die Seite „AddOns“ in den Optionen des Spiels."
L["Chat"] = "Chat"
L["Tell me in chat what the addon is doing"] = "Im Chat melden, was das Addon tut"
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Eine Zeile, wenn Euch jemand stärkt, wenn ein Gefallen als erwidert gilt und wenn ein Klick fehlschlägt, übersprungen wird oder ein Gefallen danach noch offen ist."
L["Only you see these lines. They tell a buff that was never noticed apart from somebody who could not be reached."] = "Nur Ihr seht diese Zeilen. Mit ihnen könnt Ihr einen Stärkungszauber, der nie bemerkt wurde, von jemandem unterscheiden, der nicht erreichbar war."
L["Share settings"] = "Einstellungen teilen"
L["Copy these settings as one line of text, or paste one you were given."] = "Kopiert diese Einstellungen als eine Textzeile, oder fügt eine ein, die Ihr bekommen habt."
L["A paste leaves your on switch, lock, prompt position, click log and minimap button alone. It never switches on speaking, and while speaking is on, what you say and where stays yours."] = "Beim Einfügen bleiben der Schalter „Aktivieren“, die Sperre, die Position der Anzeige, das Klick-Protokoll und das Minikartensymbol unberührt. Das Sprechen wird dabei nie eingeschaltet, und solange es eingeschaltet ist, bleiben Eure Sprüche und Euer Kanal unverändert."
L["Hide the text"] = "Text ausblenden"
L["Show my settings as text"] = "Meine Einstellungen als Text zeigen"
L["Shows these settings as one line of text in a box below, ready to select and copy. %s opens it too."] = "Zeigt diese Einstellungen als eine Textzeile in einem Feld darunter, bereit zum Markieren und Kopieren. Auch %s öffnet es."
L["Click in the box, press Ctrl+A to select it all, then Ctrl+C to copy (Cmd on a Mac)."] = "Klickt in das Feld, drückt Strg+A, um alles zu markieren, dann Strg+C zum Kopieren (am Mac Cmd)."
L["Paste settings to use them"] = "Einstellungen einfügen und übernehmen"
L["Replaces the settings on this profile with the ones in the text. %s puts yours back."] = "Ersetzt die Einstellungen dieses Profils durch die aus dem Text. %s stellt Eure alten wieder her."
L["Open the ledger"] = "Gefallen-Buch öffnen"
L["Who buffed you and with what, whether you returned it, and who you buffed unasked. Also %s, or shift-click the minimap button."] = "Wer Euch womit gestärkt hat, ob Ihr den Gefallen erwidert habt und wen Ihr unaufgefordert gestärkt habt. Auch über %s oder per Umschalt-Klick auf das Minikartensymbol."
L["Already buffed"] = "Bereits gestärkt"
L["If they already have the buff"] = "Wenn sie den Stärkungszauber schon haben"
L["Reading whether somebody has a buff needs the game's permission. See the Diagnostics tab for which of your buffs qualify."] = "Ob jemand einen Stärkungszauber hat, lässt sich nur mit Erlaubnis des Spiels auslesen. Auf dem Reiter „Diagnose“ seht Ihr, bei welchen Eurer Stärkungszauber das geht."
L["Somebody who buffed you is offered the favour back whichever you choose, even if they already have it."] = "Egal, was Ihr wählt: Bei jemandem, der Euch gestärkt hat, wird angeboten, den Gefallen zu erwidern, selbst wenn diese Person den Stärkungszauber schon hat."
L["Leave them alone (unless they buffed you)"] = "In Ruhe lassen (außer sie haben Euch gestärkt)"
L["Offer a top-up when it is running out"] = "Auffrischung anbieten, wenn er bald ausläuft"
L["Always offer, whatever they have"] = "Immer anbieten, egal was sie haben"
L["Top up when under (minutes) are left"] = "Auffrischen bei Restzeit unter (Minuten)"
L["Only offer a refresh once their remaining time drops below this. Somebody whose timer cannot be read is left alone, unless they buffed you."] = "Eine Auffrischung wird erst angeboten, wenn die Restzeit unter diesen Wert fällt. Jemand, dessen Restzeit sich nicht auslesen lässt, wird in Ruhe gelassen, außer diese Person hat Euch gestärkt."
L["Everyone nearby will be offered constantly, including people whose buff has barely ticked down. Expect to be spending mana."] = "Alle in der Nähe bekommen ständig etwas angeboten, auch Leute, deren Stärkungszauber noch fast die volle Dauer hat. Rechnet mit reichlich Manaverbrauch."
L["Nothing is read in this mode, so |cffffd100Whoever I have targeted comes first|r has no effect."] = "In diesem Modus wird nichts ausgelesen, also hat |cffffd100Mein Ziel kommt zuerst|r keine Wirkung."
L["Timing"] = "Zeitsteuerung"
L["Remember a buff for (seconds)"] = "Stärkungszauber merken für (Sekunden)"
L["How long a favour is remembered. Somebody the game cannot see may be let go sooner by |cffffd100Drop people who are probably gone|r, under Who to buff."] = "Wie lange ein Gefallen gemerkt wird. Wen das Spiel nicht sieht, der kann durch |cffffd100Wahrscheinlich Weitergezogene entfernen|r auf dem Reiter „Wen stärken“ früher entfernt werden."
L["Remember them across a reload"] = "Über ein Neuladen hinweg merken"
L["Keep favours owed through a reload or a disconnect. The clock keeps running meanwhile, so a favour that ran out is not brought back."] = "Behält offene Gefallen über ein Neuladen oder einen Verbindungsabbruch hinweg. Die Uhr läuft währenddessen weiter, also kommt ein abgelaufener Gefallen nicht zurück."
L["Stored against this character, never shared between profiles. Switching it off deletes what has already been stored."] = "Wird für diesen Charakter gespeichert, nie zwischen Profilen geteilt. Ausschalten löscht, was bereits gespeichert ist."
L["Wait before offering the same spell again (seconds)"] = "Denselben Zauber erneut anbieten nach (Sekunden)"
L["After you click, how long before that spell is offered to that player again. Covers casts that failed out of sight."] = "Wie lange es nach Eurem Klick dauert, bis dieser Zauber demselben Spieler wieder angeboten wird. Deckt Zauber ab, die unbemerkt fehlgeschlagen sind."
L["Per spell, not per person: after Fortitude the next scan can still offer them Divine Spirit. Right-clicking the prompt skips the whole person for this long."] = "Pro Zauber, nicht pro Person: Nach Seelenstärke kann derselben Person beim nächsten Suchlauf trotzdem Göttlicher Willen angeboten werden. Ein Rechtsklick auf die Anzeige überspringt die ganze Person für diese Dauer."
L["Scan every (seconds)"] = "Suchlauf alle (Sekunden)"
L["Lower is more responsive and slightly heavier."] = "Niedriger reagiert schneller und kostet etwas mehr Leistung."
L["Out of the way"] = "Aus dem Weg"
L["Keep the prompt away while you are on a mount, since casting would take you off it. It comes back when you get off."] = "Die Anzeige bleibt weg, solange Ihr auf einem Reittier sitzt, weil Ihr beim Wirken absteigen würdet. Sie kommt zurück, wenn Ihr absteigt."
L["It already stays away while you are dead, on a flight path or in a vehicle. In a fight the prompt stays as the fight found it until the fight ends."] = "Wenn Ihr tot seid, auf einer Flugroute oder in einem Fahrzeug, bleibt sie ohnehin weg. Im Kampf bleibt die Anzeige bis zum Kampfende, wie sie bei Kampfbeginn war."
L["When you click"] = "Beim Klick"
L["|cffffd100In combat.|r Blizzard freezes the prompt's macro during a fight, so these settings apply once it ends."] = "|cffffd100Im Kampf.|r Blizzard friert das Makro der Anzeige während eines Kampfes ein, also gelten diese Einstellungen erst nach dem Kampf."
L["Targeting"] = "Zielauswahl"
L["Hand my target back afterwards"] = "Danach mein Ziel wiederherstellen"
L["The prompt targets whoever it buffs, group members too. With this on, your previous target is restored right after the cast."] = "Die Anzeige nimmt jeden ins Ziel, den sie stärkt, auch Gruppenmitglieder. Ist das eingeschaltet, wird Euer vorheriges Ziel direkt nach dem Zauber wiederhergestellt."
L["Everything you can offer is cast on yourself and heard by your party, so the prompt never takes your target and has none to hand back."] = "Alles, was Ihr anbieten könnt, wirkt Ihr auf Euch selbst, und von dort erreicht es Eure Gruppe, also ändert die Anzeige nie Euer Ziel und muss auch keines wiederherstellen."
L["The prompt runs |cffffd100%s|r, the cast, then |cffffd100%s|r, except outside a fight for somebody already your target, who stays targeted."] = "Die Anzeige führt |cffffd100%s|r aus, dann den Zauber, dann |cffffd100%s|r – nur außerhalb eines Kampfes nicht bei jemandem, der schon Euer Ziel ist: Diese Person bleibt im Ziel."
L["The prompt runs |cffffd100%s|r, then the cast, and leaves them targeted."] = "Die Anzeige führt |cffffd100%s|r aus, dann den Zauber, und lässt die Person im Ziel."
L["A %s conditional only reaches your party or raid, so the macro targets everybody it buffs."] = "Eine %s-Bedingung erreicht nur Eure Gruppe oder Euren Schlachtzug, also nimmt das Makro jeden, den es stärkt, ins Ziel."
L["Speech"] = "Sprechen"
L["Say something when you buff somebody. The line is added to the macro the prompt runs, so it goes out as you talking rather than as an addon."] = "Sagt etwas, wenn Ihr jemanden stärkt. Die Zeile wird dem Makro der Anzeige hinzugefügt, also sprecht Ihr selbst und nicht ein Addon."
L["The game refuses addon-sent %s and %s outside instances, so going through the macro is what lets them work."] = "Außerhalb von Instanzen lehnt das Spiel %s und %s von Addons ab; erst über das Makro funktionieren sie."
L["Say something"] = "Etwas sagen"
L["Channel"] = "Kanal"
L["Say"] = "Sagen"
L["Yell"] = "Schreien"
L["Party"] = "Gruppe"
L["Raid"] = "Schlachtzug"
L["Emote"] = "Emote"
L["Only when returning a favour"] = "Nur beim Erwidern eines Gefallens"
L["Speak only when buffing somebody who buffed you first. Leave this on unless you want to announce every stranger you buff."] = "Es wird nur gesprochen, wenn Ihr jemanden stärkt, der Euch zuerst gestärkt hat. Lasst das eingeschaltet, außer Ihr wollt jeden Fremden ankündigen, den Ihr stärkt."
L["Phrases"] = "Sprüche"
L["Load a set"] = "Vorlage laden"
L["Replaces the lines below. Edit them afterwards as much as you like."] = "Ersetzt die Zeilen unten. Danach könnt Ihr sie nach Belieben bearbeiten."
L["Replace everything in the box below with the %s lines?"] = "Alles im Feld unten durch die Zeilen von „%s“ ersetzen?"
L["loaded the %s lines."] = "die Zeilen von „%s“ geladen."
L["One per line -- a random one is picked each time the prompt changes target. Tokens: |cff888888{name}|r the player, |cff888888{buff}|r the spell."] = "Ein Spruch pro Zeile – jedes Mal, wenn die Anzeige zu einem anderen Ziel wechselt, wird zufällig einer gewählt. Platzhalter: |cff888888{name}|r der Spieler, |cff888888{buff}|r der Zauber."
L["A macro holds 255 characters, so a line that will not fit is dropped, not cut off -- |cffffd100Roll a few|r shows what would go out. An empty box goes back to the chosen set."] = "Ein Makro fasst 255 Zeichen, also wird eine Zeile, die nicht passt, weggelassen statt abgeschnitten – |cffffd100Ein paar auswürfeln|r zeigt, was gesendet würde. Ein leeres Feld kehrt zur gewählten Vorlage zurück."
L["In character: the line is picked when you click, to fit your race, your faction and the moment -- thanks for a favour, an answer to a request, or an offer. Below are a few of this character's lines; edit them and they become your own lines instead."] = "In der Rolle: Die Zeile wird beim Klick gewählt, passend zu Eurem Volk, Eurer Fraktion und dem Moment – Dank für einen Gefallen, Antwort auf eine Bitte oder ein Angebot. Unten stehen einige Zeilen dieses Charakters; wenn Ihr sie bearbeitet, werden sie stattdessen zu Euren eigenen Zeilen."
L["Roll a few"] = "Ein paar auswürfeln"
L["Somebody"] = "Jemand"
L["A line goes out when you click, even if the cast then fails out of range or line of sight."] = "Eine Zeile geht beim Klick raus, auch wenn der Zauber danach an Reichweite oder Sichtlinie scheitert."
L["Prompt"] = "Anzeige"
L["|cffffd100In combat.|r Blizzard freezes secure frames, so changes here are saved and appear once the fight ends."] = "|cffffd100Im Kampf.|r Blizzard friert geschützte Frames ein, daher werden Änderungen hier gespeichert und sind nach dem Kampf zu sehen."
L["Stop preview"] = "Vorschau beenden"
L["Preview"] = "Vorschau"
L["Show a sample entry to style the prompt by. It stays while this window is open, then twenty seconds more or until somebody real turns up."] = "Zeigt einen Beispieleintrag an, an dem Ihr die Anzeige gestalten könnt. Er bleibt, solange dieses Fenster offen ist, danach noch zwanzig Sekunden oder bis ein echter Spieler auftaucht."
L["Locked"] = "Gesperrt"
L["Unlock to drag the prompt. It will not cast while unlocked."] = "Entsperrt die Anzeige, um sie zu verschieben. Solange sie entsperrt ist, wirkt sie keine Zauber."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "entsperrt, aber das Addon ist |cffff8080aus|r, also gibt es keine Anzeige zum Verschieben – schaltet es zuerst ein."
L["Reset position"] = "Position zurücksetzen"
L["Style"] = "Stil"
L["Where the reason colour goes"] = "Wo die Farbe des Grundes erscheint"
L["A ring around the icon reads better than a stripe at the panel edge, which ends up competing with the icon rather than framing it."] = "Ein Ring um das Symbol sieht besser aus als ein Streifen am Rand der Anzeige, der mit dem Symbol konkurriert, statt es einzurahmen."
L["The framed look has no stripe at all -- it would run down the inside of its border -- so on it the stripe settings do nothing."] = "Das Aussehen „Gerahmt“ hat gar keinen Streifen (er würde innen an seinem Rahmen entlanglaufen), daher bewirken die Streifen-Einstellungen dort nichts."
L["Ring around the icon"] = "Ring um das Symbol"
L["Stripe down the left edge"] = "Streifen am linken Rand"
L["Both"] = "Beides"
L["Neither"] = "Keins von beidem"
L["Colour it by reason"] = "Nach Grund färben"
L["Pale yellow for your own target, orange for a favour owed, deep pink for somebody who asked, sky blue for your group, violet for passers-by -- the order they are offered in."] = "Blassgelb für Euer eigenes Ziel, Orange für einen offenen Gefallen, Tiefrosa für jemanden, der darum gebeten hat, Himmelblau für Eure Gruppe, Violett für Passanten – in dieser Reihenfolge bekommen sie etwas angeboten."
L["Pale blue for your own target, amber for a favour owed, pink for somebody who asked, deeper blue for your group, grey for passers-by -- the order they are offered in."] = "Hellblau für Euer eigenes Ziel, Bernsteingelb für einen offenen Gefallen, Rosa für jemanden, der darum gebeten hat, dunkleres Blau für Eure Gruppe, Grau für Passanten – in dieser Reihenfolge bekommen sie etwas angeboten."
L["The first of those appears only while |cffffd100Whoever I have targeted comes first|r is on and |cffffd100If they already have the buff|r is not Always offer."] = "Die erste dieser Farben erscheint nur, solange |cffffd100Mein Ziel kommt zuerst|r eingeschaltet ist und |cffffd100Wenn sie den Stärkungszauber schon haben|r nicht auf „Immer anbieten“ steht."
L["Reason colours"] = "Farben der Gründe"
L["The colour-blind set keeps the reasons apart for red-green colour blindness, in colours that differ in lightness too."] = "Der Satz „Für Farbenblinde“ hält die Gründe bei Rot-Grün-Sehschwäche auseinander, mit Farben, die sich auch in der Helligkeit unterscheiden."
L["Standard"] = "Standard"
L["Colour-blind friendly"] = "Für Farbenblinde"
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off, and the framed look has no stripe."] = "Es gibt nichts mehr zu färben: Der Ring wird hinter dem Symbol gezeichnet, das ausgeschaltet ist, und das Aussehen „Gerahmt“ hat keinen Streifen."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask, and the framed look has no stripe."] = "Es gibt nichts mehr zu färben: Das Abrunden des Symbols ersetzt den Ring durch eine Maske, und das Aussehen „Gerahmt“ hat keinen Streifen."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off."] = "Es gibt nichts mehr zu färben: Der Ring wird hinter dem Symbol gezeichnet, das ausgeschaltet ist."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask."] = "Es gibt nichts mehr zu färben: Das Abrunden des Symbols ersetzt den Ring durch eine Maske."
L["There is nothing left to colour: the framed look has no stripe."] = "Es gibt nichts mehr zu färben: Das Aussehen „Gerahmt“ hat keinen Streifen."
L["Accent colour"] = "Akzentfarbe"
L["Used for the ring, the stripe, or both -- whichever the setting above asks for."] = "Wird für den Ring, den Streifen oder beides verwendet – je nachdem, was die Einstellung darüber vorgibt."
L["Look"] = "Aussehen"
L["Glass -- dark panel, soft shadow"] = "Glas – dunkler Hintergrund, weicher Schatten"
L["Framed -- flat panel, thin border"] = "Gerahmt – flacher Hintergrund, dünner Rahmen"
L["Minimal -- text only, no panel"] = "Minimal – nur Text, kein Hintergrund"
L["Panel colour"] = "Hintergrundfarbe"
L["Getting your attention"] = "Aufmerksamkeit wecken"
L["When someone buffs you"] = "Wenn Euch jemand stärkt"
L["Pulse keeps breathing until you have returned the favour or they are gone. Flash once is easy to miss if you were looking elsewhere."] = "„Pulsieren, bis erledigt“ pulsiert weiter, bis Ihr den Gefallen erwidert habt oder die Person weg ist. „Einmal aufblitzen“ ist leicht zu übersehen, wenn Ihr gerade woanders hinschaut."
L["It lights the spell icon, sweeps the stripe, and with Effects on Full the panel catches the light. With none of those showing it has nothing to do."] = "Das Leuchten erscheint um das Zaubersymbol und läuft über den Streifen, und wenn „Effekte“ auf „Voll“ steht, leuchtet der Hintergrund auf. Ist nichts davon zu sehen, hat das Leuchten nichts zu tun."
L["Pulse until dealt with"] = "Pulsieren, bis erledigt"
L["Flash once"] = "Einmal aufblitzen"
L["Nothing"] = "Nichts"
L["Effects"] = "Effekte"
L["Full: light crosses the panel when a buff lands, a refused buff shakes the text, and the prompt fades out after your last buff."] = "Voll: Wenn ein Stärkungszauber gelingt, zieht Licht über den Hintergrund, schlägt einer fehl, wackelt der Text, und nach Eurem letzten Stärkungszauber blendet die Anzeige langsam aus."
L["Calm: none of that movement. The prompt still fades in, and the glow set above still works."] = "Ruhig: nichts von dieser Bewegung. Die Anzeige blendet trotzdem sanft ein, und das oben eingestellte Leuchten funktioniert weiterhin."
L["The Minimal look has no panel, so no light crosses it. In a fight, Stay quiet in combat keeps the outcome still as well."] = "Das Aussehen „Minimal“ hat keinen Hintergrund, also zieht auch kein Licht darüber. Im Kampf hält „Im Kampf ruhig bleiben“ auch die Rückmeldung still."
L["Full"] = "Voll"
L["Calm -- less movement"] = "Ruhig – weniger Bewegung"
L["Play a sound"] = "Sound abspielen"
L["Play a sound when somebody new reaches the top of the queue."] = "Spielt einen Sound ab, wenn jemand Neues an die Spitze der Warteschlange rückt."
L["Sound"] = "Sound"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(nicht geladen)|r"
L["Only when somebody buffed me"] = "Nur wenn mich jemand gestärkt hat"
L["Off, every new person on the prompt makes a noise -- including strangers you happen to walk past."] = "Ist dies aus, macht jede neue Person in der Anzeige ein Geräusch – auch Fremde, an denen Ihr zufällig vorbeilauft."
L["%s is silent. Pick a sound above."] = "%s ist stumm. Wählt oben einen Sound."
L["Position and size"] = "Position und Größe"
L["Put it"] = "Platzieren"
L["Three places that are already right. Dragging the prompt afterwards leaves this blank, because it is then not on one of them."] = "Drei Stellen, die schon passen. Verschiebt Ihr die Anzeige danach, bleibt dieses Feld leer, weil sie dann an keiner davon steht."
L["X offset"] = "X-Versatz"
L["Y offset"] = "Y-Versatz"
L["Width"] = "Breite"
L["Height"] = "Höhe"
L["Scale"] = "Skalierung"
L["Opacity"] = "Deckkraft"
L["Stay quiet in combat"] = "Im Kampf ruhig bleiben"
L["A click still casts in combat, and the prompt flashes to say what happened -- red if it failed. With this on it stays dimmed and still for the fight."] = "Ein Klick wirkt auch im Kampf, und die Anzeige blitzt auf, um zu zeigen, was passiert ist – rot, wenn es fehlgeschlagen ist. Ist dies eingeschaltet, bleibt sie für die Dauer des Kampfes abgedunkelt und still."
L["It stays on screen in a fight on purpose: your key binding would still cast the frozen macro if it were hidden."] = "Die Anzeige bleibt im Kampf absichtlich sichtbar: Wäre sie ausgeblendet, würde Eure Tastenbelegung das eingefrorene Makro trotzdem ausführen."
L["Text"] = "Text"
L["First line"] = "Erste Zeile"
L["Tokens: {name} {reason} {count} {class} {buff} {time}"] = "Platzhalter: {name} {reason} {count} {class} {buff} {time}"
L["Show a second line"] = "Zweite Zeile anzeigen"
L["Needs a prompt at least %d pixels tall at this font size."] = "Braucht bei dieser Schriftgröße eine Anzeige von mindestens %d Pixeln Höhe."
L["|cff888888{name}|r who   |cff888888{reason}|r why   |cff888888{count}|r how many more   |cff888888{class}|r their class   |cff888888{buff}|r the spell"] = "|cff888888{name}|r wer   |cff888888{reason}|r warum   |cff888888{count}|r wie viele noch   |cff888888{class}|r Klasse   |cff888888{buff}|r der Zauber"
L["|cff888888{time}|r what theirs has left, on a top-up and nowhere else"] = "|cff888888{time}|r Restdauer des vorhandenen Stärkungszaubers, nur bei einer Auffrischung"
L["The second line always shows the reason."] = "Die zweite Zeile zeigt immer den Grund."
L["Wording: your target"] = "Wortlaut: Euer Ziel"
L["Your target outranks everyone, including a favour owed, while that is switched on under Who to buff and the game can see they lack it."] = "Euer Ziel geht allen vor, auch einem offenen Gefallen, solange das auf dem Reiter „Wen stärken“ eingeschaltet ist und das Spiel sehen kann, dass der Stärkungszauber fehlt."
L["Wording: buffed you"] = "Wortlaut: hat Euch gestärkt"
L["Wording: in your group"] = "Wortlaut: in Eurer Gruppe"
L["Wording: nearby"] = "Wortlaut: in der Nähe"
L["Wording: topping one up"] = "Wortlaut: Auffrischung"
L["Used instead of the four above when their buff is about to run out, which only the refresh mode offers. |cffffd100{time}|r is how long theirs has left."] = "Wird statt der vier darüber verwendet, wenn der Stärkungszauber der Person bald ausläuft – das gibt es nur, wenn Auffrischungen angeboten werden. |cffffd100{time}|r ist die verbleibende Dauer."
L["Wording: state unknown"] = "Wortlaut: Status unbekannt"
L["Used when the game will not let addons read whether they already have it."] = "Wird verwendet, wenn das Spiel Addons nicht auslesen lässt, ob die Person den Stärkungszauber schon hat."
L["Font"] = "Schriftart"
L["Font size"] = "Schriftgröße"
L["Text colour"] = "Textfarbe"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while |cffffd100Colour names by class|r is on."] = "Bleibt die Textfarbe auf Weiß, wird der Text auf hellem Hintergrund von selbst dunkel. Andere Farben werden so verwendet, wie Ihr sie wählt, außer bei Namen, solange |cffffd100Namen in Klassenfarbe|r eingeschaltet ist."
L["Colour names by class"] = "Namen in Klassenfarbe"
L["Icon and queue"] = "Symbol und Warteschlange"
L["Show spell icon"] = "Zaubersymbol anzeigen"
L["Icon size"] = "Symbolgröße"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Bleibt innerhalb der Anzeige – macht sie zuerst höher oder breiter, um ein größeres Symbol zu bekommen."
L["The icon is held at %d to fit a prompt %d wide."] = "Das Symbol bleibt bei %d, damit es in eine %d breite Anzeige passt."
L["The icon is held at %d to fit a prompt %d high."] = "Das Symbol bleibt bei %d, damit es in eine %d hohe Anzeige passt."
L["Round the icon off"] = "Symbol abrunden"
L["Masks the icon into a circle. Reads more like a portrait than a spell, so it is off by default."] = "Maskiert das Symbol zu einem Kreis. Das wirkt eher wie ein Porträt als wie ein Zauber, daher ist es standardmäßig aus."
L["The mask replaces the ring, so move the reason colour to the stripe if you want both. The glow when somebody buffs you follows the circle."] = "Die Maske ersetzt den Ring, legt also die Farbe des Grundes auf den Streifen, wenn Ihr beides wollt. Das Leuchten, wenn Euch jemand stärkt, folgt dem Kreis."
L["Show the global cooldown on the icon"] = "Globale Abklingzeit auf dem Symbol anzeigen"
L["Sweeps the spell icon while the global cooldown runs, like your action bars, so you can see when the next press will go through."] = "Zeigt auf dem Zaubersymbol die globale Abklingzeit an, wie Eure Aktionsleisten, damit Ihr seht, wann der nächste Klick durchgeht."
L["Not in a fight while Stay quiet in combat is on."] = "Nicht im Kampf, solange „Im Kampf ruhig bleiben“ eingeschaltet ist."
L["Show how many are waiting"] = "Anzahl der Wartenden anzeigen"
L["List the next few below"] = "Die nächsten darunter auflisten"
L["How many to list"] = "Wie viele auflisten"
L["Diagnostics"] = "Diagnose"
L["Log every click to chat"] = "Jeden Klick im Chat protokollieren"
L["Prints what the button held when you clicked and what the game did with it. Noisy; for working out why a cast did not happen."] = "Gibt aus, was die Schaltfläche beim Klick enthielt und was das Spiel damit gemacht hat. Erzeugt viele Meldungen; gedacht, um herauszufinden, warum ein Zauber nicht gewirkt wurde."
L["What this client allows"] = "Was dieser Client erlaubt"
L["Class: |cffffffff%s|r"] = "Klasse: |cffffffff%s|r"
L["learned: |cff00ff00yes|r"] = "erlernt: |cff00ff00ja|r"
L["learned: |cff808080no|r"] = "erlernt: |cff808080nein|r"
L["missing-check: |cff00ff00works|r"] = "Aurenprüfung: |cff00ff00funktioniert|r"
L["missing-check: |cffff8080blocked|r"] = "Aurenprüfung: |cffff8080blockiert|r"
L["this client has never heard of spell %s, so Manners will never offer this one. That is a mistake in Manners -- please report it."] = "dieser Client kennt Zauber %s überhaupt nicht, daher wird Manners ihn nie anbieten. Das ist ein Fehler in Manners – bitte meldet ihn."
L["this client doesn't know spell %s, so somebody already carrying that version may be offered this anyway. That is a mistake in Manners -- please report it."] = "dieser Client kennt Zauber %s nicht, daher bekommt jemand, der diese Version schon trägt, diesen Stärkungszauber womöglich trotzdem angeboten. Das ist ein Fehler in Manners – bitte meldet ihn."
L["Where the missing-check is blocked, addons cannot read that aura: players are still offered, but some may already have the buff."] = "Wo die Aurenprüfung blockiert ist, können Addons diese Aura nicht auslesen: Spieler bekommen den Stärkungszauber trotzdem angeboten, aber manche haben ihn vielleicht schon."
L["Nothing to report: this character has no buffs it can put on another player."] = "Nichts zu melden: Dieser Charakter hat keine Stärkungszauber, die er auf andere Spieler wirken kann."
L["What has broken"] = "Aufgetretene Fehler"
L["(%d in all this session, %d kept -- |cffffd100%s|r)"] = "(%d insgesamt in dieser Sitzung, %d aufbewahrt – |cffffd100%s|r)"
L["(%d in all this session -- |cffffd100%s|r)"] = "(%d insgesamt in dieser Sitzung – |cffffd100%s|r)"
L["Nothing has broken this session."] = "In dieser Sitzung sind keine Fehler aufgetreten."
L["Reporting a bug"] = "Fehler melden"
L["Hide the report"] = "Bericht ausblenden"
L["Copy for a bug report"] = "Für Fehlerbericht kopieren"
L["Opens a box with the build, what this client allows, the settings that matter and anything that has broken, ready to copy."] = "Öffnet ein Feld mit der Version, den Angaben unter „Was dieser Client erlaubt“, den wichtigen Einstellungen und allen aufgetretenen Fehlern, bereit zum Kopieren."
L["Switched off -- the prompt this fight froze stays up until it ends, and a press still casts it."] = "Ausgeschaltet – die Anzeige, die dieser Kampf eingefroren hat, bleibt bis zum Kampfende sichtbar, und ein Klick wirkt noch ihren Zauber."
L["Switched off -- no prompt will appear."] = "Ausgeschaltet – es erscheint keine Anzeige."
L["Unlocked, but in this fight the prompt stays as the fight found it, and a press still casts it; it can be dragged once the fight ends."] = "Entsperrt, aber in diesem Kampf bleibt die Anzeige, wie sie bei Kampfbeginn war, und ein Klick wirkt noch ihren Zauber; verschieben lässt sie sich nach dem Kampf."
L["Unlocked -- the prompt this fight froze stays up until it ends, and a press still casts it; then it can be dragged."] = "Entsperrt – die Anzeige, die dieser Kampf eingefroren hat, bleibt bis zum Kampfende sichtbar, und ein Klick wirkt noch ihren Zauber; danach lässt sie sich verschieben."
L["Unlocked, and snoozed until %s -- the prompt stays up to be dragged, casting nothing, until you lock it."] = "Entsperrt und pausiert bis %s – die Anzeige bleibt zum Verschieben sichtbar und wirkt nichts, bis Ihr sie sperrt."
L["Unlocked -- the prompt is up to be dragged and casts nothing until you lock it (%s)."] = "Entsperrt – die Anzeige ist zum Verschieben sichtbar und wirkt nichts, bis Ihr sie sperrt (%s)."
L["Snoozed until %s -- in this fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "Pausiert bis %s – in diesem Kampf bleibt die Anzeige, wie sie bei Kampfbeginn war, und folgt der Pause, sobald der Kampf vorbei ist."
L["Snoozed until %s, %s from now -- no prompt until then."] = "Pausiert bis %s, noch %s – bis dahin keine Anzeige."
L["Nothing to do: %s"] = "Nichts zu tun: %s"
